public class Main {
    public static void main(String[] args) {
        int x = {x};
        int y = {y};

        x = x ^ y;
        y = x ^ y;
        x = x ^ y;

        System.out.println("x 现在是 " + x);
        System.out.println("y 现在是 " + y);
    }
}
